package main

import (
	"bufio"
	"fmt"
	"os"
	"strings"

	"github.com/shopspring/decimal"
)

type LoanRec struct {
	LrAcct      string          // PIC X(6) @0 len=6
	LrPrincipal decimal.Decimal // PIC 9(7)V99 @6 len=9
	LrRate      decimal.Decimal // PIC 9(2)V99 @15 len=4
	LrYears     int64           // PIC 9(2) @19 len=2
}

// Standalone working-storage items (VALUE shown after '=')
var WsEofFlag string          // PIC X len=1 = "N"
var WsInterest decimal.Decimal // PIC 9(9)V99 len=11 = 0
var WsTotal decimal.Decimal    // PIC 9(11)V99 len=13 = 0
var WsCount int64              // PIC 9(5) len=5 = 0
var WsPrinEd string            // PIC Z,ZZZ,ZZ9.99 len=12
var WsIntEd string             // PIC ZZZ,ZZZ,ZZ9.99 len=14
var WsTotalEd string            // PIC ZZ,ZZZ,ZZZ,ZZ9.99 len=17

var loanRec LoanRec
var loanRecords []string
var loanIdx int

func main() {
	WsEofFlag = "N"
	WsInterest = decimal.NewFromInt(0)
	WsTotal = decimal.NewFromInt(0)
	WsCount = 0

	// OPEN INPUT LOAN-FILE
	f, err := os.Open("input.dat")
	if err != nil {
		// if file not found, treat as empty
		loanRecords = []string{}
	} else {
		scanner := bufio.NewScanner(f)
		// allow long lines
		buf := make([]byte, 0, 64*1024)
		scanner.Buffer(buf, 10*1024*1024)
		for scanner.Scan() {
			line := scanner.Text()
			// scanner strips newline, keeps other content
			// COBOL LINE SEQUENTIAL: record is line content, pad with spaces to 21 if shorter
			// Need to preserve spaces inside line; scanner.Text keeps them.
			// Pad/truncate to 21
			if len(line) < 21 {
				line = line + strings.Repeat(" ", 21-len(line))
			} else if len(line) > 21 {
				line = line[:21]
			}
			loanRecords = append(loanRecords, line)
		}
		f.Close()
	}
	loanIdx = 0

	MAIN_PARA()
}

func MAIN_PARA() {
	READ_PARA()
	for WsEofFlag != "Y" {
		PROCESS_PARA()
	}
	// CLOSE LOAN-FILE already closed / no-op
	SUMMARY_PARA()
}

func READ_PARA() {
	if loanIdx >= len(loanRecords) {
		WsEofFlag = "Y"
		return
	}
	line := loanRecords[loanIdx]
	loanIdx++

	// parse fixed width
	// LR-ACCT @0 len6
	loanRec.LrAcct = line[0:6]

	// LR-PRINCIPAL @6 len9 9(7)V99
	rawPrin := line[6 : 6+9]
	loanRec.LrPrincipal = parseImpliedDecimal(rawPrin, 2)

	// LR-RATE @15 len4 9(2)V99
	rawRate := line[15 : 15+4]
	loanRec.LrRate = parseImpliedDecimal(rawRate, 2)

	// LR-YEARS @19 len2 9(2)
	rawYears := line[19 : 19+2]
	loanRec.LrYears = parseIntField(rawYears)
}

func PROCESS_PARA() {
	// COMPUTE WS-INTEREST ROUNDED = LR-PRINCIPAL * LR-RATE * LR-YEARS / 100
	tmp := loanRec.LrPrincipal.Mul(loanRec.LrRate).Mul(decimal.NewFromInt(loanRec.LrYears))
	tmp = tmp.Shift(-2) // divide by 100
	rounded := tmp.Round(2) // half away from zero for positive
	WsInterest = storeDecimal(rounded, 9, 2)

	// ADD WS-INTEREST TO WS-TOTAL
	WsTotal = WsTotal.Add(WsInterest)
	WsTotal = storeDecimal(WsTotal, 11, 2)

	// ADD 1 TO WS-COUNT
	WsCount = WsCount + 1
	if WsCount >= 100000 {
		WsCount = WsCount % 100000
	}
	if WsCount < 0 {
		WsCount = ((WsCount % 100000) + 100000) % 100000
	}

	// MOVE
	WsPrinEd = formatPrin(loanRec.LrPrincipal)
	WsIntEd = formatIntEd(WsInterest)

	fmt.Printf("%s %s %s\n", loanRec.LrAcct, WsPrinEd, WsIntEd)

	READ_PARA()
}

func SUMMARY_PARA() {
	WsTotalEd = formatTotal(WsTotal)
	fmt.Printf("RECORDS: %05d\n", WsCount)
	fmt.Printf("TOTAL INTEREST: %s\n", WsTotalEd)
}

// helpers

func parseImpliedDecimal(raw string, scale int32) decimal.Decimal {
	// raw is digits, may contain spaces
	s := strings.TrimSpace(raw)
	if s == "" {
		return decimal.NewFromInt(0)
	}
	// remove spaces inside
	s = strings.ReplaceAll(s, " ", "")
	if s == "" {
		return decimal.NewFromInt(0)
	}
	// It should be all digits, possibly empty
	// Parse as integer
	// Use decimal to avoid overflow
	d, err := decimal.NewFromString(s)
	if err != nil {
		// fallback: extract digits
		filtered := ""
		for _, ch := range s {
			if ch >= '0' && ch <= '9' {
				filtered += string(ch)
			}
		}
		if filtered == "" {
			return decimal.NewFromInt(0)
		}
		d, _ = decimal.NewFromString(filtered)
	}
	// implied decimal: divide by 10^scale
	return d.Shift(-scale)
}

func parseIntField(raw string) int64 {
	s := strings.TrimSpace(raw)
	if s == "" {
		return 0
	}
	s = strings.ReplaceAll(s, " ", "")
	if s == "" {
		return 0
	}
	var n int64
	for _, ch := range s {
		if ch >= '0' && ch <= '9' {
			n = n*10 + int64(ch-'0')
		}
	}
	// keep low-order digits that fit 2 digits: COBOL would do on move? but here field is 2 digits, raw is exactly 2 digits
	// if larger, low-order kept? input width is 2, so not needed
	if n >= 100 {
		n = n % 100
	}
	return n
}

func storeDecimal(v decimal.Decimal, intDigits int, scale int32) decimal.Decimal {
	// round/truncate already done, now apply high-order truncation if integer part exceeds intDigits
	// v has scale digits
	s := v.StringFixed(scale) // includes sign and dot
	neg := false
	if strings.HasPrefix(s, "-") {
		neg = true
		s = s[1:]
	}
	parts := strings.SplitN(s, ".", 2)
	intPart := parts[0]
	fracPart := ""
	if len(parts) == 2 {
		fracPart = parts[1]
	} else {
		fracPart = strings.Repeat("0", int(scale))
	}
	if len(intPart) > intDigits {
		intPart = intPart[len(intPart)-intDigits:]
		// reconstruct
		newStr := intPart + "." + fracPart
		if neg {
			newStr = "-" + newStr
		}
		d, _ := decimal.NewFromString(newStr)
		return d
	}
	return v
}

func formatWithPicture(v decimal.Decimal, pic string) string {
	// generic formatter for Z , 9 pictures with one dot
	dotIdx := strings.Index(pic, ".")
	var beforePic, afterPic string
	if dotIdx >= 0 {
		beforePic = pic[:dotIdx]
		afterPic = pic[dotIdx+1:]
	} else {
		beforePic = pic
		afterPic = ""
	}
	fracDigits := len(afterPic) // number of 9s after dot
	// count integer placeholders
	intCap := 0
	for _, ch := range beforePic {
		if ch == 'Z' || ch == '9' {
			intCap++
		}
	}
	// get fixed string
	s := v.Abs().StringFixed(int32(fracDigits))
	// split
	parts := strings.SplitN(s, ".", 2)
	intStr := parts[0]
	fracStr := ""
	if len(parts) == 2 {
		fracStr = parts[1]
	} else {
		if fracDigits > 0 {
			fracStr = strings.Repeat("0", fracDigits)
		}
	}
	// handle overflow truncation (should already be done, but do again for safety)
	if len(intStr) > intCap {
		intStr = intStr[len(intStr)-intCap:]
	}
	// pad left with zeros to intCap
	if len(intStr) < intCap {
		intStr = strings.Repeat("0", intCap-len(intStr)) + intStr
	}
	// find first non-zero
	firstNonZero := intCap // meaning all zero
	for i, ch := range intStr {
		if ch != '0' {
			firstNonZero = i
			break
		}
	}
	threshold := firstNonZero
	if firstNonZero == intCap {
		threshold = intCap - 1
	}
	// build before part
	outBefore := []rune{}
	pDigitIdx := 0 // index in intStr for next placeholder
	placeholdersBefore := 0 // count of placeholders already emitted
	// We need to know placeholdersBefore for comma suppression: it's pDigitIdx count at that point
	for _, ch := range beforePic {
		if ch == 'Z' || ch == '9' {
			digit := rune(intStr[pDigitIdx])
			if pDigitIdx < threshold {
				// Z suppressed -> space, 9 would still be digit but in this pic 9 only at last position, which is beyond threshold when all zero we keep it
				if ch == 'Z' {
					// if digit is '0' and suppressed, space
					outBefore = append(outBefore, ' ')
				} else {
					// 9 always prints, but if we are in suppressed zone and ch == '9' could it be suppressed? In our pics 9 is last and threshold ensures it's not suppressed when all zero case? Actually threshold = cap-1, so last placeholder idx = cap-1 equals threshold? pDigitIdx < threshold would be false for last, so it prints.
					// For other cases where firstNonZero not at end, pDigitIdx < threshold means leading zeros before first non-zero, but 9 shouldn't appear there (only Z there). So fine.
					outBefore = append(outBefore, digit)
				}
			} else {
				outBefore = append(outBefore, digit)
			}
			pDigitIdx++
			placeholdersBefore++
		} else if ch == ',' {
			// suppress if placeholdersBefore <= threshold (if threshold is cap-1 all commas suppressed)
			// placeholdersBefore is number of placeholders before this comma
			if placeholdersBefore <= threshold {
				outBefore = append(outBefore, ' ')
			} else {
				outBefore = append(outBefore, ',')
			}
		} else {
			outBefore = append(outBefore, ch)
		}
	}
	result := string(outBefore)
	if dotIdx >= 0 {
		result += "." + fracStr
	}
	// negative sign handling if needed (not required for this program)
	if v.Sign() < 0 {
		// place minus at last space position or at front
		// COBOL would have sign separate, but not needed
		// simple: replace first space before digit with '-'
		runes := []rune(result)
		for i := len(runes) - 1; i >= 0; i-- {
			if runes[i] == ' ' {
				// find if there's a digit to the right that is not space
				hasDigit := false
				for j := i + 1; j < len(runes); j++ {
					if runes[j] >= '0' && runes[j] <= '9' {
						hasDigit = true
						break
					}
				}
				if hasDigit {
					runes[i] = '-'
					break
				}
			}
		}
		// if no space found, prefix
		if string(runes) == result {
			result = "-" + result[1:]
		} else {
			result = string(runes)
		}
	}
	return result
}

func formatPrin(v decimal.Decimal) string {
	return formatWithPicture(v, "Z,ZZZ,ZZ9.99")
}

func formatIntEd(v decimal.Decimal) string {
	return formatWithPicture(v, "ZZZ,ZZZ,ZZ9.99")
}

func formatTotal(v decimal.Decimal) string {
	return formatWithPicture(v, "ZZ,ZZZ,ZZZ,ZZ9.99")
}
